// Proactive Business English B2 · Syria Edition · Book 1 · Unit 3 — Answer Key (separate book)
const L = require('./lib');
const { p, h1, h2, h3, pb, sp, stage, box, dlg, table, C } = L;
const out = [];
const sample = (title, paras) => box(title, paras, 'FFFFFF', C.navy);
const note = t => p(`_${t}_`, { color: '595959' });

out.push(h1('Answer Key · Unit 3  The Case Against a Decision Already Half-Taken'));
out.push(p('_Proactive Business English · B2 · Book 1 · Syria Edition_', { color: '7F7F7F' }));
out.push(box('How to use this key', [
  'Every task has an answer. Where the task is open, the key gives a **full sample answer**. Samples show one good B2 answer – learners\' own answers will be different and that is correct.',
  '⚠ **This is the unit the level exists for, and it is the hardest in Book 1.** **Unit 1 taught a learner to sort a file; Unit 2 taught them what a sentence does to a person.** ⚠ **Unit 3 asks them to argue upward against something their employer has already said out loud that he wants** — **and to do it by giving ground, admitting a weakness, and making their opponent\'s case better than he made it.** **Every one of those three feels like losing, and the unit\'s whole job is to show that they are how you are read.**',
  '⚠ **Expect resistance at 3.1 and 3.3 specifically, and expect it to be about workplace reality rather than about language.** **A learner will say: in my office, if I write that the other side\'s case is the best thing in ten years, that is the sentence that gets quoted and I am finished.** ⚠ **That objection is sometimes correct and must not be waved away.** **The honest answer is in the unit: the costly concession only works in a paper that also carries a figure and a threshold** — **conceding without a load-bearing figure is simply surrender, and the unit never asks for it.**',
  '⚠ **The three words that drive the unit are Mr Ayoub\'s: _put it better._** **They are not *you are wrong* and not *I disagree*.** ⚠ **A learner who understands that a four-page paper winning eleven arguments got three words of reply has understood the unit before it starts.**',
  '⚠ **Word counts.** Stage 6 asks for **80 words or more** and stage 7 for **200 to 240**. ⚠ **Cycle 7\'s exam task is Writing Part 1 again, at 40 to 50 words and 10 marks**, because the two Writing parts alternate through the book: **odd units Part 1, even units Part 2**, with one deliberate exchange at Units 20 and 21 in Book 2.',
  '⚠ **The exam practice is Reading Part 3: multiple choice on one longer text, six questions, A–D.** **The text is Mr Attar\'s note to the management committee and it restates the unit\'s argument from the reader\'s side**, which is deliberate: ⚠ **a learner who has done the unit can answer the questions from the unit, and should be made to locate the sentence anyway.**',
], C.grey, C.navy));

// ===================== 3.1 =====================
out.push(h2('3.1  The concession that costs you something'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **The second half is the question: did it cost them anything?** **Most learners will describe a concession that cost nothing and did not persuade them**, which is the evidence the cycle needs and they supply it themselves.'));
out.push(p('**b**  The **second** costs something. ⚠ **The first is a shape, not a statement** — *of course… but* — **and every reader knows the shape.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Whether you are visibly poorer for having written it — whether a reader who stopped there would think you had lost.**  2 ⚠ **Because the reader was waiting for it**, and *but* tells him the real argument starts after the comma, so he stops reading the concession and reads for what follows.'));
out.push(p('⚠ **The exchange to replay is the last one.** **Nour asks what is left of her paper if she concedes the revenue case, and Nadia says: one figure and one request** — ⚠ **which is a paper, and four pages of eleven arguments was not.** **That is the unit\'s economics in one line: the concession does not weaken the paper, it is what makes a paper possible.**'));
out.push(p('**Language box – Practise (sample, three):**  _**1** *(against a new price list)* **The customers who have asked for one are the nine who place the largest orders, and they have asked three times. Full stop. I have nothing to set against that.**  **2** *(against night working)* **The second press pays for itself in four months on nights and the figures are Bassel\'s and I have checked them. Full stop. There is no version of the arithmetic in which this does not pay.**  **3** *(against moving the Ghouta run)* ⚠ **Mondays and Wednesdays suit the two largest customers on that run better than Thursdays ever did, and I know because I moved it and the complaints halved. Full stop. The best argument against what I am about to ask for is a thing I did myself.**_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'The volume figures are not directly comparable with our current arrangements.'],
  ['B', 'Where did that come from?'],
  ['A', 'It is… the seasons are different, and the price basis.'],
  ['B', 'Did you work it out?'],
  ['A', 'I compared them. They are four times ours.'],
  ['B', 'So they are directly comparable.'],
  ['A', 'Yes.'],
  ['B', 'Then what is the clause doing in your paper?'],
  ['A', 'Getting the strongest thing in his case out of the way.'],
  ['B', 'And what does the paper look like without it?'],
  ['A', 'Shorter. And it has to concede the volume in the second sentence, which is what I was avoiding.'],
]));
out.push(p('⚠ **Role card 2 produces the unit\'s most uncomfortable finding and it is worth ten minutes.** ⚠ **The pretended counter-figure is almost always placed exactly where the other side is strongest**, because that is where the writer most wants cover. **It is also where a reader checks first.**'));
out.push(stage('3R', 'Perform'));
out.push(p('Listeners write the free concession and the costly one, and what the costly one cost. **Typical errors:** *of course… but* in any of its forms (*while it is true that · granted that · admittedly*) · a concession followed immediately by a counter-figure, which is a *but* with the word removed · ⚠ **and the content fault, which is a concession of something the other side does not actually claim.** **Conceding a point nobody made is the most expensive-looking free concession there is.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['What I hold', 'The best thing about the other side', 'What conceding it costs me', 'What is left of my case'], [
  ['the contract should be capped', '⚠ **the revenue case is better than anything in ten years**', '⚠ **the whole revenue argument — nine of my eleven points**', '⚠ **one figure: sixty-one per cent**'],
  ['we should not open on Fridays', 'the street is busy until one and we have the staff', 'the demand argument entirely', 'the half-day, and what a half-day costs to open'],
  ['the price list must be revised', 'two revisions in a month confuses nine trade customers', 'the *do it now* argument', 'the eleven under-priced quotations already out'],
  ['we should keep the plater', '⚠ **twelve per cent is a lot and we took it without asking anybody else**', '⚠ **my own prudence argument**', 'nobody in Aleppo plates to our standard, which I have checked'],
], [1.4, 2, 1.5, 1.6]));
out.push(stage('4R', 'Report – sample'));
out.push(sample(null, ['"I hold that the contract should be capped. The best thing about the other side is that the revenue case is better than anything we have been offered in ten years. Conceding it costs me the whole revenue argument — nine of my eleven points. What is left is one figure."', '⚠ **Count how many cases got shorter: it should be all of them.** ⚠ **Then ask the question that lands the cycle: which speaker sounded most likely to be believed?** **It is always the one who gave most away, and the class can hear it**, which is a more durable lesson than being told.']));
out.push(stage('5', 'Read'));
out.push(p('**1** Before: **54 words.** After: **68 words** — ⚠ **the honest version is fourteen words longer**, which is the point: **conceding properly costs words at this paragraph and saves nine arguments later.**  **2** ⚠ *Not directly comparable.* **Four words, technical-sounding, and false** — **the figures are directly comparable and she compared them.** **She wrote it because the volume figure is the strongest thing in his case and she wanted it out of the way**, ⚠ **and a reader who checks it, which Mr Attar would in an afternoon, finds she fudged the only figure she did not need to fudge.**  **3** ⚠ **What the paper is** — *an argument about one figure, and the figure is sixty-one per cent* — ⚠ **and that if the figure is wrong he can stop reading.** **That is a risk, and it is the only reason he read it twice.**'));
out.push(stage('6', 'Write with help – sample (141 words)'));
out.push(sample(null, [
  '**THE FRIDAY NOTE — PARAGRAPH 1, BEFORE AND AFTER. 27 February. H. Mourad.**',
  '**Before.** _There are of course arguments for opening on Fridays, and the demand is not in dispute, but a number of practical considerations need to be weighed, and the staffing position is not as straightforward as has been suggested._',
  '⚠ **Thirty-eight words. Two concessions, neither costing anything, and one clause about staffing that is not true — the staffing is straightforward, because two women are already on a Friday rota at Mezzeh.**',
  '**After.** _The demand is there and it is bigger than I said in August. The street is busy until one, the nine trade customers who asked have asked three times, and Lina says the counter would take a hundred and twenty on a Friday morning. I have nothing to set against any of that. What follows is not an argument that the demand is smaller than it looks. It is an argument about one number, and the number is the four hours we would be open._',
  '⚠ **Eighty-two words, forty-four more, and it gives away the demand argument completely.**',
  '**The clause I am most ashamed of is *the staffing position is not as straightforward as has been suggested*.** It is nine words, it sounds careful, and it is false — and it is false about the one thing the person reading it can check in a minute by looking at the rota on the wall behind him.',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['The other side\'s case given its own figures', '✓ three of them, and one is Lina\'s'],
  ['No *but* after the concession', '✓ ⚠ **and no *while it is true that* either**'],
  ['A fudged clause found and taken out', '✓ ⚠ **and the sample names why it is the worst place to fudge — the rota is on the wall behind the reader**'],
  ['What the paper rests on, as a single thing', '✓ the four hours'],
  ['Both word counts, with the honest version longer', '✓ 38 and 82'],
], [3.2, 2.8]));
out.push(p('⚠ **Sample band-4 review:** _"Criterion: what the paper rests on, as a single thing. The line I am marking is **_It is an argument about one number, and the number is the four hours we would be open._** What I found: four hours is a fact and not a figure. A figure has a base and a source and something to compare it with — what you mean is the takings per open hour, and until you say that the reader cannot check anything."_ ⚠ **That review is right and it anticipates 3.4.** **Read it out when you get there.**'));
out.push(stage('6R', 'Share'));
out.push(p('Two or three read only their concession. ⚠ **The class answers one question: did the speaker sound as though they had lost?** ⚠ **The ones who did are the ones who have done the exercise**, and saying so out loud is what gets the rest of the room to risk it.'));
out.push(stage('7', 'Write freely – sample (229 words)'));
out.push(sample(null, [
  'I lost an argument in 2019 by winning all of it, and I did not understand that until this month.',
  'It was about a supplier who delivered late about one time in five. I had the dates. I had eleven instances over fourteen months, the hours lost on each, and a comparison with two other suppliers who were dearer and never late. I wrote three pages and every line of it was true and checkable, and I did not concede one thing.',
  'What I did not say, because it would have cost me the argument, was that the man had supplied us through two years when nobody else would, on terms nobody else offered, and that my employer knew it and I knew it and the whole workshop knew it.',
  'My employer read the three pages and said we would keep him. He did not argue with any of my eleven instances, because there was nothing wrong with them. He simply did not answer the paper at all, and I thought he was being sentimental.',
  'He was weighing something I had refused to put on the page, which meant I had made him weigh it alone and in silence, against a document that behaved as though it did not exist.',
  'The version I would write now opens by saying what the man did in those two years, with the dates, and then asks for one thing: a penalty clause.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **Sample:** _"Criterion: did the concession cost the writer anything? The line I copied is **_I had made him weigh it alone and in silence, against a document that behaved as though it did not exist._** What I found: that is the cost of the free concession stated better than the unit states it. The paper did not fail to persuade; it made itself irrelevant to the actual decision."_'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect two of three texts in which the costly concession came from the person who went on to win, and expect at least one writer who still thinks they won on the arguments.** ⚠ **Do not correct them.** **The unit does the correcting at 3.7, where Mr Attar says what the eleven-point version would have got: four pages of reply and nothing else.**'));
out.push(box('Homework – marking note', [
  'The final text is marked for the content.',
  '⚠ **The second part asks for the other side\'s best version with its own figures, and then a count of what is left.** ⚠ **The count is the piece to check.** **A learner whose case is the same size after the concession has not conceded** — **a real costly concession always deletes something, usually several things, and the deletion is the evidence.**',
], C.lblue, C.navy));

// ===================== 3.2 =====================
out.push(pb());
out.push(h2('3.2  I may be wrong about this'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **The second half — who found out first — is the one that teaches.** **The answer is very rarely the person who was wrong**, and that is the case for writing the admission yourself.'));
out.push(p('**b**  The **first** is a hedge; the **second** is a structure. ⚠ **The difference is a consequence attached to a named thing.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **That she had never written a paper against a decision her employer had half-taken** — the last line of B1 Unit 24, written in August and sealed.  2 ⚠ **It invites the reader to agree with you and stop** — **a free way out of the argument, which he will take.**'));
out.push(p('⚠ **Hala\'s formulation is the one to put on the board:** ⚠ **the same information doing the opposite work.** **_I may be wrong_ with no consequence says *do not take me too seriously*; with a total consequence it says *take this one figure seriously, because everything stands on it*.** ⚠ **And the closing line is the reason it works: nobody ever tells anybody where to push, so a reader who has been shown the weak point reads the rest as something built rather than something sold.**'));
out.push(p('**Language box – Practise (sample, three):**  _**1** ⚠ **I may be wrong that the counter would take a hundred and twenty on a Friday morning. It is Lina\'s estimate after three weeks. If it is half that, the Friday case fails and nothing else in this note matters.**  **2** **I may be wrong that nobody in Aleppo plates to our standard. I have asked two platers and there are five. If one of the three I have not asked can do it, the twelve per cent was avoidable and I should have found out in March.**  **3** ⚠ **I may be wrong that the eleven quotations are still live. If they have lapsed, the under-pricing costs us nothing and this is a note about a filing habit.**_'));
out.push(stage('3', 'Practise – sample with role card 1'));
out.push(dlg(null, [
  ['A', 'I may of course be wrong about all this, as I have been before.'],
  ['B', 'You may well be, and I think you are. Shall we leave it there?'],
  ['A', '…'],
  ['B', 'That is what the sentence buys you. What exactly might be wrong?'],
  ['A', 'The hundred and twenty on a Friday morning. It is Lina\'s estimate and she has been at the counter three weeks.'],
  ['B', 'And if it is wrong, what happens to the rest?'],
  ['A', 'If it is half that, there is no case at all. Everything else in the note is about how to open, not whether.'],
  ['B', 'Then write that.'],
  ['A', 'I may be wrong about the hundred and twenty. If it is half that, nothing else in this note matters.'],
  ['B', 'And when would I otherwise have found out?'],
  ['A', 'On the first Friday, with four staff in and a street that closes at one.'],
]));
out.push(p('⚠ **The point of role card 1 is that B takes the free way out immediately and A has nothing to say.** ⚠ **Do not let the pair skip that silence** — **it is four seconds long and it is the whole argument for the cycle.** **Run it twice if the first attempt is laughed off.**'));
out.push(stage('3R', 'Perform'));
out.push(p('Listeners write the admission and its consequence and mark the consequence total, partial or nil. **Typical errors:** *as I have been before* and *of course*, both of which generalise the admission away from the paper · an admission attached to something nothing depends on · ⚠ **and the content fault, which is a learner who writes a perfect load-bearing admission and then adds *though I am fairly confident*** — **six words that undo it completely.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The case', 'What I may be wrong about', 'If I am wrong, then…', 'Total, partial or nil?'], [
  ['cap the Beirut contract', 'the sixty-one per cent', '⚠ **nothing else in the paper matters**', '⚠ **total**'],
  ['open on Fridays', 'Lina\'s hundred and twenty', 'there is no case at all', '**total**'],
  ['keep the plater', 'that nobody else plates to our standard', 'the twelve per cent was avoidable', '**total**'],
  ['revise the price list now', 'that the eleven quotations are still live', '⚠ **it becomes a note about filing, not money**', '**partial**'],
], [1.4, 1.7, 1.7, 1.2]));
out.push(stage('4R', 'Report – sample'));
out.push(sample(null, ['"My case is that we should open on Fridays. I may be wrong about Lina\'s hundred and twenty on a Friday morning — she has been at the counter three weeks. If I am, there is no case at all, because everything else in the note is about how to open and not whether. That is a total consequence."', '⚠ **Count the total consequences, and then do the harder thing: ask each speaker with a nil consequence what they were really hedging about.** ⚠ **The answer is usually a person rather than a fact** — *I did not want Mr Attar to think I had not checked* — **and that is a sentence for a different paragraph or for nowhere.**']));
out.push(stage('5', 'Read'));
out.push(p('**1** ⚠ **Name one thing rather than general fallibility · attach a total consequence · and tell the reader where to stop.**  **2** ⚠ **Because of what the alternative is.** **If she does not say it and the figure is wrong, he reads four pages built on a mistake and finds out from somebody else** — ⚠ **and then what he has learned is not that her arithmetic was wrong but that she did not know it could be.**  **3** ⚠ **It is measured, not guessed: she timed Mr Attar checking it without telling him why.** ⚠ **A priced check cannot be postponed for want of time, which is the ground every unchecked figure in that building has been left on.**'));
out.push(stage('6', 'Write with help – sample (137 words)'));
out.push(sample(null, [
  '**THE FRIDAY NOTE — PARAGRAPH 3. 28 February. H. Mourad.**',
  '⚠ **I may be wrong about the hundred and twenty. If I am, there is no case in this note and you should stop at paragraph 4.** The figure is what the Mezzeh counter would take on a Friday morning between nine and one. It is Lina\'s estimate from three weeks at the counter, set against the Saturday takings for the same four hours over the last eleven Saturdays, which are on the daily sheets. The working is on one page and it is arithmetic and not judgement, except for Lina\'s three weeks, which is judgement and is the weak half. ⚠ **If you want it checked properly, it is four Fridays of counting and we would know in a month.**',
  '⚠ **The sentence I argued with myself about is *you should stop at paragraph 4*.** **No note tells its reader where to stop.** ⚠ **It is in because the alternative is that you read three pages about rotas and street closures and find out on the first Friday that the premise was one woman\'s guess.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['One named thing, not general fallibility', '✓ the hundred and twenty'],
  ['A consequence, stated totally if it is total', '✓ *there is no case in this note*'],
  ['Where to stop reading', '✓ paragraph 4'],
  ['A source belonging to the other side', '✗ ⚠ **none** — **the Saturday sheets are the firm\'s own; there is no outside figure here, and the sample should say so rather than leave the slot empty**'],
  ['The check priced, and the price measured', '✗ ⚠ **four Fridays is priced and not measured** — **and it is a month, which is too long to be a check; say so and offer the smaller one**'],
], [3.2, 2.8]));
out.push(p('⚠ **Sample band-4 review, and it is the best in the cycle:** _"Criterion: the check priced and measured. The line I am marking is **_it is four Fridays of counting and we would know in a month._** What I found: a month is not a check, it is a trial. Your reader has to decide before then. The real check is half an hour with eleven Saturday sheets, and you have already done it — you just did not call it one."_ ⚠ **This is the finding that distinguishes a check from a trial, and the unit does not make it.** **A peer did.**'));
out.push(stage('6R', 'Share'));
out.push(p('Two or three read only their first two sentences. ⚠ **The class says what it would go and check and how long it thinks it would take.** ⚠ **Where the class\'s estimate is much longer than the writer\'s, the writer has priced a trial and called it a check** — **which is the sample review\'s finding and is worth naming every time it appears.**'));
out.push(stage('7', 'Write freely – sample (233 words)'));
out.push(sample(null, [
  'Everything the workshop I used to work in did about scrap rested on a figure of eleven per cent, and nobody alive there knew where it came from.',
  'It was the assumed loss on sheet steel: eleven per cent of every sheet became offcut and was sold for weight. Every quotation we issued had it in. Every costing had it in. The foreman knew it, the office knew it, and the owner quoted it to customers as though it were a property of steel.',
  'In my fourth year I weighed the offcut for a fortnight, which took about ten minutes a day, because a lorry came for it on Fridays and there was a scale at the gate. It was six and a half per cent. We had been pricing in four and a half points of loss that did not exist, on everything, for a period nobody could date.',
  'What would have changed is nothing dramatic. Our prices were competitive and our margin was better than anybody thought. But the figure had been used to refuse two jobs in my time on the grounds that they were marginal, and they were not marginal.',
  'Nobody had checked it because checking it was somebody else\'s job and because the figure had the authority of having always been there. It took twenty minutes a week for two weeks and the scale was already at the gate.',
  'I never found out who first wrote eleven.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **Sample:** _"Criterion: how long would the check actually take? The line I copied is **_It took twenty minutes a week for two weeks and the scale was already at the gate._** What I found: that is the sentence the whole text is for, and it is at the end. It belongs in your second paragraph, because a reader who has it early reads the rest as negligence and a reader who gets it late reads it as bad luck."_'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect all three checks to take under an hour, and expect at least one figure older than everybody who now uses it.** ⚠ **Name the mechanism: a figure acquires authority by surviving, and the longer it survives unchecked the more authority it has and the less likely anybody is to check it.** **That is the opposite of how it should work and it is reliable enough to plan around.**'));
out.push(box('Homework – marking note', [
  'The final text is marked for the content.',
  '⚠ **The second part asks the learner to time themselves checking the figure their own work rests on.** **Some will do it and the results are the best material in the unit.** ⚠ **Ask for the measured time and the outcome separately** — **and when a figure turns out to be wrong, give the whole lesson to it.**',
], C.lblue, C.navy));

// ===================== 3.3 =====================
out.push(pb());
out.push(h2('3.3  The strongest version of the other side'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **The second half — have you ever? — is almost always no**, and the reason given is almost always that nobody asked them to. **Nobody ever asks anybody to.**'));
out.push(p('**b**  The **second** is the strongest version: ⚠ **three concrete gains in the owner\'s terms.** **The first is a report of a feeling held by unnamed people, which is the weakest form there is.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **That it is better than she thought** — board at a price never offered, the second press on nights all year, no more pricing against a season — **and that her own case changed shape as a result.**  2 ⚠ **That she may convince herself**, and if his case is better than hers this is how she will find out, **and then she has to say so.**'));
out.push(p('⚠ **The structural line of the cycle is Bassel\'s:** ⚠ **_which is the paper. You found it by writing his side properly, and you would not have found it any other way._** **Nour\'s case moves from *the contract is bad* to *sixty-one per cent is too much of us for one man to hold*** — ⚠ **a narrower, checkable claim that is the whole of the rest of Book 1.** **Steelmanning is presented here not as fairness but as a method of discovering what you actually think.**'));
out.push(p('**Language box – Practise (sample, three gains in their terms):**  _**(The case for taking the plater\'s twelve per cent without shopping around.)** **1** He has plated for us since the second year and has never returned work. **2** A plater who knows our gauge tolerances costs nothing to brief, and the three we have not asked would each cost a trial run and a fortnight. **3** ⚠ **Twelve per cent of the plating is about one and a half per cent of a carton, and we have never lost an order on one and a half per cent.** ⚠ **Written out, that is a better case than the one I was making against it, and the only thing left of mine is that we did not ask.**_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['B', 'Read me their best case.'],
  ['A', 'That two revisions of the price list in one month would confuse the nine trade customers who read it, and that the second revision is three weeks away anyway, and that reissuing now means reissuing twice.'],
  ['B', 'Did you like writing it?'],
  ['A', 'No. It is right.'],
  ['B', 'And did your own case survive?'],
  ['A', '…No. The list should wait three weeks.'],
  ['B', 'Then what is still true?'],
  ['A', 'That eleven quotations are out at the old price and they are live for fourteen days. That is not about the list at all.'],
  ['B', 'So you have a much smaller paper.'],
  ['A', 'One page, about eleven quotations, and it has nothing to do with the thing I was arguing about on Monday.'],
]));
out.push(p('⚠ **Role card 2 must be allowed to end in a loss, and the teacher\'s job is to make that the good outcome.** ⚠ **B does not rescue A.** **The two honest answers are to say so, or to find the thing that is still true and write a much smaller paper** — **and the sample finds the second, which is the better teaching case because it shows the method paying even when the case collapses.**'));
out.push(stage('3R', 'Perform'));
out.push(p('Listeners write the three gains in the other side\'s terms and the *not that X, but that Y*. **Typical errors:** gains written in the opponent\'s vocabulary rather than the owner\'s (*they claim there would be efficiencies*) · three gains that are one gain three times · ⚠ **and the content fault, which is a *not that X, but that Y* in which Y is as wide as X.** **If the claim did not narrow, the other side was not written properly.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['What I oppose', 'Three gains, in their terms', 'Did I like writing it?', 'My case now: not that X, but that Y'], [
  ['the Beirut contract', '⚠ **board at a price never offered · the second press on nights all year · no seasonal guessing**', '**no**', '⚠ **not that the contract is bad, but that 61% is too much of us for one man to hold**'],
  ['taking the plater\'s 12%', 'never returned work · no briefing cost · 1.5% of a carton', 'no', '⚠ **not that 12% was too much, but that we did not ask three platers**'],
  ['revising the list now', 'two revisions confuse nine readers · the next is three weeks off', '⚠ **no, and my case did not survive**', '⚠ **not that the list is wrong, but that eleven live quotations are under-priced**'],
], [1.3, 2.2, 1, 1.9]));
out.push(stage('4R', 'Report – sample'));
out.push(sample(null, ['"I oppose revising the price list now. The three gains are that two revisions in a month confuse the nine trade customers who read it, that the next revision is three weeks away, and that reissuing now means reissuing twice. I did not like writing it, and my case did not survive it. What is left is not that the list is wrong, but that eleven live quotations are out at the old price."', '⚠ **Count how many cases changed shape, and then ask directly whether anybody\'s case did not survive.** ⚠ **Let them say so, and treat it as the best result in the room** — **because a learner who has abandoned a position by writing the other side will use the method again, and one who has merely narrowed a position may believe they got away with it.**']));
out.push(stage('5', 'Read'));
out.push(p('**1** ⚠ **The board price at eleven hundred a month** — nobody has ever asked the mill, so nobody knows what it is. ⚠ **She has said in paragraph 10 that she has not asked and why**, and a reader is entitled to notice that **the largest gain in the case for accepting is a figure she has declined to obtain.**  **2** ⚠ **The third** — **two years of saying the Homs seasons went wrong because nobody counted walk-in trade is an argument for a contract that removes the guess from sixty-one per cent of the business.** **If her own evidence supports them, it supports them.**  **3** ⚠ **From *the contract is bad* to *sixty-one per cent is too much of us for one man to hold*** — **a narrower claim, and the only one that survived writing the other side properly.**'));
out.push(stage('6', 'Write with help – sample (148 words)'));
out.push(sample(null, [
  '**THE PLATING — THE CASE FOR PAYING THE TWELVE PER CENT. 1 March. B. Nassif. Written as Mr Ayoub would write it if he had the costing.**',
  '⚠ **This is not a summary of what was said in March. It is the best case for having paid it that can be made on the figures, and it is stronger than the case anybody made at the time.**',
  table(['', 'The gain', 'The figure behind it'], [
    ['**1**', '**A plater who has never returned work in eleven years.**', 'nought rejections on about 4,100 batches; the three platers we have not asked are an unknown rejection rate each'],
    ['**2**', '**No briefing cost.** He knows our gauge tolerances and our marking.', '⚠ **a trial run and a fortnight each for the other three — about 30,000 and six weeks in total, which nobody costed in March**'],
    ['**3**', '**Twelve per cent of plating is about 1.5 per cent of a finished carton.**', '⚠ **and we have never lost an order on 1.5 per cent — I have checked nine lost orders and none of them turned on price at all**'],
  ], [0.5, 2.6, 3]),
  '**The second gain is the one I cannot size properly and it is probably the biggest.** Nobody costed the alternative in March. I have put 30,000 and six weeks on it here and both are estimates, and I have said so at paragraph 7.',
  '**The third gain uses my own evidence against me.** I have argued for two years that we lose orders on delivery and not on price, and if that is true then 1.5 per cent is not the question.',
  '**Writing this took an hour and a half and changed my paper.** I am no longer arguing that twelve per cent was too much. I am arguing that we accepted it without asking anybody, which is a habit and not a price.',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['A sentence saying this is not a summary', '✓'],
  ['Gains in their terms, with figures behind them', '✓'],
  ['The gain that cannot be sized, named as possibly the biggest', '✓ and the estimates are labelled estimates'],
  ['Your own evidence used for their case where it fits', '✓ ⚠ **and it is the strongest row** — two years of *we lose on delivery, not price*'],
  ['*Not that X, but that Y* — the narrowed claim', '✓ ⚠ **and Y is a different kind of thing from X, which is better than narrower**'],
], [3.4, 2.6]));
out.push(p('⚠ **Sample band-4 review:** _"Criterion: your own evidence used for their case. The line I am marking is **_if that is true then 1.5 per cent is not the question._** What I found: you have conceded more than you noticed. If price never decides our orders, then your remaining case — that we did not shop around — is also not about money, and you have not said what it is about. It is about whether anybody checks anything, and that is a bigger paper."_'));
out.push(stage('6R', 'Share'));
out.push(p('Two or three read only their *not that X, but that Y*. ⚠ **The class judges whether Y is narrower than X.** ⚠ **If it is not, the other side was not written properly and the exercise should be sent back** — **the test is mechanical and the class can apply it without the teacher.**'));
out.push(stage('7', 'Write freely – sample (231 words)'));
out.push(sample(null, [
  'A woman called Rana put my own argument back to me in a meeting in 2016 and I have thought about it perhaps forty times since.',
  'I had been arguing for two months that we should stop using a courier who was cheap and slow, and I had the figures: eleven late deliveries in a quarter, four of them to our two largest customers. I was right about all of it.',
  'She said: so your case is that we should pay thirty per cent more for a courier, in a quarter when we are nine per cent down, to prevent eleven late deliveries of which the customers complained about two, and the two who complained still ordered the following month. Then she said that if she were me she would make the case on the two complaints and not on the eleven, because the eleven include seven nobody noticed, and a case built on things nobody noticed invites the answer that nobody noticed them.',
  'It was my argument, stated better, and it was a refutation. I had never separated the deliveries that were late from the deliveries that cost us something, and in two months of being right I had not once asked which of the eleven mattered.',
  'We kept the courier. Eighteen months later we changed, on a paper I wrote about two complaints.',
  'She did not win the argument. She told me what my argument was.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **Sample:** _"Criterion: did the writer change their mind, or only their respect? The line I copied is **_in two months of being right I had not once asked which of the eleven mattered._** What I found: neither. You changed your method, and that is why you can date the paper that eventually worked. The text should say that at the top instead of at the bottom."_'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect two of three to have had the point won by the person who put the argument better, and expect all three to remember it years later.** ⚠ **That durability is worth naming: nobody remembers being out-argued and everybody remembers being understood**, and the second is what this cycle manufactures on purpose.'));
out.push(box('Homework – marking note', [
  'The final text is marked for the content.',
  '⚠ **The second part asks for an hour on the best version of the thing they most disagree with, and one line on what happened to their case.** ⚠ **Read the one line first.** **If the case is unchanged, the hour was not spent properly** — **and in a class of ten, two or three cases should not survive at all.**',
], C.lblue, C.navy));

// ===================== 3.4 =====================
out.push(pb());
out.push(h2('3.4  The one figure that decides it'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Expect at least two learners not to know the base of a percentage they use weekly.** **That is the cycle, and it arrives in the first ninety seconds.**'));
out.push(p('**b**  The **second** can be checked. ⚠ **_Unacceptably high_ is an adjective with no number in it and cannot be agreed or disagreed with, only asserted.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **The number, the base and the source — and a fourth that nobody does: the threshold.**  2 ⚠ **It had no base.** *Of turnover* **is not a base: whose turnover, over what period, at which prices, and with what else held constant.**'));
out.push(p('⚠ **Mr Attar\'s line is the one to keep:** ⚠ **a percentage without its base is a feeling with a number stuck to it.** **And his fourth requirement is the cycle\'s real content and almost nobody in any office does it:** ⚠ **say what the figure would have to be for your paper to fail.** ⚠ *At forty per cent I would not be writing this paper.* **Without it, you call sixty-one high and he calls it moderate, for ever.**'));
out.push(p('**Language box – Practise (sample, one figure in four parts):**  _**The number:** thirty-eight per cent. **The base:** of total turnover for the twelve months to 31 December, being sales invoiced to Ms Tannous, at invoiced prices, with nothing else changed. **The source:** the ledger; her order numbers cross-checked against our delivery notes. ⚠ **The threshold:** at fifty per cent I would have written to Mr Ayoub about her a year ago, and I did not, which is how I know forty is my real line and not a number I invented for a paper._'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['B', 'At what number would you stop minding?'],
  ['A', '…'],
  ['B', 'Take your time.'],
  ['A', 'I do not know. I have never thought about it as a number.'],
  ['B', 'So you call sixty-one high.'],
  ['A', 'Yes.'],
  ['B', 'And Mr Ayoub calls it manageable, and neither of you can be shown to be wrong, and you will both say it again next week.'],
  ['A', 'How do I find my line?'],
  ['B', 'Look for the figure you have already lived with. What have you run at without writing a paper?'],
  ['A', 'Thirty-eight. To Ms Tannous. For a year, and it never once worried me.'],
  ['B', 'Then your line is somewhere above thirty-eight, and you can defend forty because you have lived at thirty-eight.'],
]));
out.push(p('⚠ **The method in role card 2 is the one to teach and the unit only hints at it:** ⚠ **do not invent a threshold, find the one you have already lived with.** **A threshold derived from a figure the writer has tolerated without complaint is unarguable** — ⚠ **and it is also true, which an invented number is not.**'));
out.push(stage('3R', 'Perform'));
out.push(p('Listeners write the number, base, source and threshold, and say which part came from the other side. **Typical errors:** a base that stops at *of turnover* · a source given as *the system* or *the figures* · a threshold invented on the spot and therefore indefensible · ⚠ **and the content fault, which is a learner who gives a threshold in the wrong direction** — *I would be happy below sixty* **is not a threshold, it is the same adjective with a number in it.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The figure', 'The base — of what, whose, when', 'The source', 'The threshold'], [
  ['**61%**', 'of our total turnover, 12 months to 31 Dec, his volume at his price, nothing else changed', '⚠ **the ledger; his letter of 9 Jan, p.2**', '⚠ **40% — I have lived at 38 for a year**'],
  ['**38%**', 'of the same turnover, Tannous invoiced sales at invoiced prices', 'the ledger; her orders against our delivery notes', '**never reached one; this is the base case**'],
  ['**12%**', 'of the plating charge only, not of a carton', 'the plater\'s letter of 28 February', '⚠ **3% of a finished carton — above that I would have shopped around**'],
  ['**6.5%**', 'of sheet weight lost as offcut, measured over a fortnight', '⚠ **the gate scale, weighed by me, 14 days**', '**9% — above that the two refused jobs were right to refuse**'],
], [1, 2.2, 1.5, 1.6]));
out.push(stage('4R', 'Report – sample'));
out.push(sample(null, ['"The figure is sixty-one per cent. Its base is our total turnover for the twelve months to 31 December, with his stated volume at his stated price added and nothing else changed. It comes from our ledger and from his own letter of 9 January, page two. And at forty per cent I would stop minding, because I have run at thirty-eight to Ms Tannous for a year and it has never once worried me."', '⚠ **Count the figures with no statable base** — **it is usually about half** — ⚠ **and then count the thresholds, and expect nought.** **Then tell the class that the second number is nought in every room this has been run in**, which is why the move is worth so much: it is free and nobody makes it.']));
out.push(stage('5', 'Read'));
out.push(p('**1** ⚠ **The volume and the price are from his own letter of 9 January, page 2** — **so the only part he can argue with is the ledger, and the ledger is the one thing in the building nobody has ever disputed.** **She says so twice on purpose.**  **2** ⚠ **By finding the figure she had already lived with.** **She had run at thirty-eight per cent to Ms Tannous for a year without worrying, so forty was not invented for the paper — it is where she already was**, ⚠ **and she did not know it until she had to write a number.**  **3** ⚠ **It turns yes-or-no into a shape.** **Mr Ayoub can cap the volume, stage it, or keep Ms Tannous on at a reduced quantity** — **all real answers.** ⚠ **Without the threshold his only available answers were yes and no.**'));
out.push(stage('6', 'Write with help – sample (151 words)'));
out.push(sample(null, [
  '**THE OFFCUT — THE FIGURE. 2 March. B. Nassif. Working at appendix A, one page.**',
  table(['', 'The part', 'The paper says'], [
    ['**the number**', '**6.5 per cent**', '*six and a half per cent*'],
    ['⚠ **the base**', '⚠ **of what, whose, when, how', '⚠ **_of the weight of sheet steel issued to the saw, over the fourteen working days from 10 to 27 February, weighed as offcut at the gate scale on collection, with no change to the job mix_**'],
    ['**the source**', 'the gate scale', '*weighed by me on fourteen consecutive days; the figures are on the scale docket book*'],
    ['⚠ **the comparison**', '⚠ **the figure in use**', '⚠ **_eleven per cent, which is in every costing this workshop issues and which nobody can date or source_**'],
    ['⚠ **the threshold**', '⚠ **the line**', '⚠ **_at nine per cent the two jobs we refused in 2022 as marginal were correctly refused. At six and a half they were not._**'],
    ['**the check**', 'timed', '*twenty minutes a day, and the scale is already at the gate*'],
  ], [1.5, 1.8, 3.3]),
  '⚠ **The comparison row is the one that matters here and the unit does not ask for it.** **A new figure that replaces an old one has to say what the old one was and where it came from**, and in this case the answer is that nobody knows, which is itself the finding.',
  '⚠ **The threshold took me a week, because writing it meant going back to two refused jobs and recalculating them.** **At nine per cent we were right to refuse them. At six and a half we were not, and one of them went to a competitor who still has the customer.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['The base in the sentence, including *nothing else changed*', '✓ *with no change to the job mix*'],
  ['Which part of the figure is theirs, said twice', '✗ ⚠ **no part of it is theirs** — **this is an internal measurement, and the sample should say so; the slot is not always fillable and the honest move is to name the absence**'],
  ['A threshold, and how it was arrived at', '✓ ⚠ **and it is arrived at by recalculating two real decisions, which is the strongest form**'],
  ['What the threshold makes possible', '✗ ⚠ **not stated** — **it makes it possible to reopen the two refused jobs, and that should be in the paper**'],
  ['The check priced and the working on one page', '✓'],
], [3.2, 2.8]));
out.push(p('⚠ **Sample band-4 review:** _"Criterion: what the threshold makes possible. The line I am marking is **_At six and a half they were not._** What I found: you have proved two decisions were wrong and then stopped. The reader cannot act on that. One sentence — *I propose we quote the Nassar job again at the measured rate* — turns a correction into an ask, and without it this reads as a paper about who was wrong."_ ⚠ **That review connects 3.4 to 3.5 and should be read out at the start of the next cycle.**'));
out.push(stage('6R', 'Share'));
out.push(p('Two or three read only their threshold sentence. ⚠ **The class says what answers it makes available that yes and no did not.** ⚠ **Where the answer is *none*, the threshold is in the wrong direction or is not tied to a decision** — **and the remedy is role card 2: find the figure you have already lived with, or the decision the figure would change.**'));
out.push(stage('7', 'Write freely – sample (227 words)'));
out.push(sample(null, [
  'We have argued about staff turnover in my department for three years, in adjectives.',
  'The figure is about a quarter a year. I say that is high. The head of the division says it is normal for the sector and has said so in three annual reviews. Neither of us has ever produced a number that would settle it, and neither of us has ever asked what the other one would accept.',
  'The base is not agreed either, which I only noticed last year. I count everybody who leaves, including two fixed-term contracts that ended. He counts permanent staff who resign. On his base it is about seventeen per cent and on mine it is twenty-six, and we have spent three years arguing about whether a number is high without establishing that we were discussing two different numbers.',
  'What would end it is a line. If he said that above twenty per cent on his own base he would fund a retention review, we would both know what we were looking at, and the argument would become a measurement, which is a thing that can be finished.',
  'I am going to propose twenty in my next paper and say that I have lived with seventeen for two years without complaining, which is true, and which makes the twenty defensible rather than tactical.',
  'Three years, and neither of us has ever written a number.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **Sample:** _"Criterion: what would the threshold have to be to satisfy both sides? The line I copied is **_we have spent three years arguing about whether a number is high without establishing that we were discussing two different numbers._** What I found: the threshold cannot be set until the base is agreed, and that is a separate and earlier paper. Yours is the base paper and it is one page."_'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect all three arguments to have run over a year and expect none to contain a proposed number.** ⚠ **The second finding is the one to add, from the sample: in at least one case the two sides are using different bases and nobody has noticed** — **and where that is so, the threshold paper cannot be written until the base paper has been.**'));
out.push(box('Homework – marking note', [
  'The final text is marked for the content.',
  '⚠ **The second part asks the learner to take a threshold to the person who disagrees with them.** ⚠ **Collect what happened, and expect the commonest outcome to be the one Mr Attar produces in 3.7: the other person names a different number and the argument becomes twenty minutes long.** **That outcome is a success and the class should be told so, because to the learner it can feel like having lost.**',
], C.lblue, C.navy));

// ===================== 3.5 =====================
out.push(pb());
out.push(h2('3.5  What you are not asking for'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **The second half — what the smallest version would have been — is usually answered easily and has usually never been offered.**'));
out.push(p('**b**  The **second** can be granted this week. ⚠ **It is a yes with a number in it: he keeps the contract, keeps the term, and the figure moves.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **The contract, the three years, and his January position** — *the best thing in ten years*, which paragraph 5 agrees with using his own figures.  2 ⚠ **That you must be satisfied if he grants it** — **a smaller ask you would refuse to accept is a tactic, and a reader finds that out at the moment it matters most.**'));
out.push(p('⚠ **The diagnostic question is Nadia\'s and it is the one to drill:** ⚠ **what would he have to do to agree with you — all of it?** ⚠ **If part of the answer is *be seen to change his mind in front of four people*, you have attached a cost to agreeing that has nothing to do with the argument**, and it is a cost he pays and you do not. ⚠ **And the formulation of the remedy is exact: you cannot write a paper in which he was never wrong; you can write one in which agreeing with you is not the same act as being wrong.**'));
out.push(p('**Language box – Practise (sample, three):**  _**1** *(Fridays)* **I am not asking you to open on Fridays. I am asking you to open on the four Fridays of April and count the mornings.**  **2** *(the plater)* **I am not asking you to change platers. I am asking you to let me get two quotations before the next plating order, so that next time we know what twelve per cent was worth.**  **3** *(the price list)* ⚠ **I am not asking you to reissue the list. I am asking you to let me telephone the eleven customers whose quotations are live and correct them before they lapse.**_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'I am not asking you to change platers. I am asking for two quotations before the next order.'],
  ['B', 'And if I say yes, are you satisfied?'],
  ['A', 'Yes.'],
  ['B', 'Say that again.'],
  ['A', '…If the two quotations come in higher, I am satisfied.'],
  ['B', 'And if they come in lower?'],
  ['A', 'Then I would come back and ask you to change platers.'],
  ['B', 'So you are not satisfied. You are asking for the evidence to make the bigger ask.'],
  ['A', 'That is not dishonest.'],
  ['B', 'It is not dishonest and it is not what you wrote. Write *I am asking for two quotations, and if they are lower I will come back to you about the plater* — and then you have said it, and he can say yes to the whole of it.'],
]));
out.push(p('⚠ **Role card 2 ends better than the unit does and teachers should use the sample\'s resolution.** ⚠ **The remedy for a tactical small ask is not to abandon it — it is to declare the second step.** **_If they are lower I will come back to you about the plater_ is honest, it is still a small ask, and the reader can grant the whole sequence in one decision**, which is better for both.'));
out.push(stage('3R', 'Perform'));
out.push(p('Listeners write the big ask, the hidden cost and the smaller ask, and say whether the speaker would be satisfied. **Typical errors:** a negative half with no positive half after it · a smaller ask that is the big ask with a softer verb (*consider declining*) · ⚠ **and the content fault, which is a smaller ask that is a first instalment with the second instalment unstated.** **The remedy is to state it.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['What I want', 'What they would have to do to agree', 'The smaller ask', 'Would I be satisfied?'], [
  ['the Beirut contract capped', '⚠ **write to Mr Dallal, and be seen to change his mind in front of four people**', '⚠ **cap year one at 600 and ask the mill**', '⚠ **yes — 35% is below my stated 40**'],
  ['a different plater', 'reverse a decision he took with Bassel in March', 'two quotations before the next order', '⚠ **yes, and if they are lower I will come back — and I have said so**'],
  ['the price list reissued', 'reissue twice in a month to nine readers', 'telephone the eleven live quotations', '**yes; the list can wait three weeks'],
  ['the inspection list extended', 'nothing — nobody owns the list', '⚠ **one line added, and my name against it**', '**yes'],
], [1.3, 1.9, 1.9, 1.2]));
out.push(p('⚠ **The fourth row is the one to point at.** ⚠ **An ask whose hidden cost is *nothing, because nobody owns the thing* is an ask that has never been made for no reason at all** — **and in most workplaces there are several.** **Ask the class for theirs.**'));
out.push(stage('4R', 'Report – sample'));
out.push(sample(null, ['"I want a different plater. To agree they would have to reverse a decision taken with Bassel in March. The smaller ask is two quotations before the next order. And I would be satisfied — and if the quotations are lower I will come back about the plater, and I have written that down."', '⚠ **Count the big asks whose hidden cost was *being seen to change their mind*: it is usually most of them.** ⚠ **Then ask who said they would not be satisfied, and congratulate them** — **and then show them the sample\'s remedy, which is to declare the second step rather than drop the first.**']));
out.push(stage('5', 'Read'));
out.push(p('**1** ⚠ **To refuse the proposal · to reduce the term · to keep Ms Tannous in the chain if the figures do not support it.** **The third is the one that costs the writer something, which is what makes the negative half real.**  **2** ⚠ *If you cap the first year at six hundred, I am satisfied, and I will not come back in June with the same paper and a different figure in it.* **It is tied to the threshold named in paragraph 6: thirty-five is below forty.**  **3** ⚠ **It costs a letter, and it is the only thing in the file that cannot be undone.** **Everything else can be changed later; a woman who found the company for them and learns from somebody else what has been decided cannot be unlearned.**'));
out.push(stage('6', 'Write with help – sample (154 words)'));
out.push(sample(null, [
  '**THE PLATING — WHAT I AM ASKING FOR. 3 March. B. Nassif.**',
  '⚠ **I am not asking you to change platers. I am not asking you to reopen the March decision, and I am not asking for the twelve per cent back.**',
  '**What I am asking for is two things, and both can be done before the next plating order on the 18th.**',
  table(['', 'The ask', 'What it costs you', 'What it answers'], [
    ['**1**', '**Two quotations from the three platers in Aleppo we have never asked**, before the 18th.', '⚠ **nothing — I will get them**', '⚠ **what the twelve per cent was worth, which nobody knows**'],
    ['**2**', '**A line in the order book: every plating order over 100,000 gets two quotations.**', '**your initials, once**', '**the habit, which is the actual subject of this note**'],
  ], [0.5, 2.9, 1.5, 2.1]),
  '⚠ **Neither of these asks you to say the March decision was wrong, and that is deliberate** — **paragraph 4 says it probably was not, with the rejection figures in it.** **A quotation is not a reversal; it is the same arrangement with a number beside it.**',
  '⚠ **And the honest part: if the two quotations come in higher, I am satisfied and I will say so in writing.** **If they come in lower, I will come back to you about the plater, and I am telling you that now rather than letting you find it out in April.**',
  '**The second ask is the smaller one and it is the one I care about.** It costs your initials and it is the only part of this that outlives the current order.',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['A negative half that gives something up', '✓ *I am not asking for the twelve per cent back*'],
  ['A *what it costs you* column, with small costs in it', '✓ *nothing* and *your initials, once*'],
  ['Agreeing stated as not an admission, with a cross-reference', '✓ paragraph 4, with figures'],
  ['A promise not to come back, tied to the threshold', '✗ ⚠ **the opposite, and better** — **the second step is declared instead of promised away, which 3.5 should have allowed for**'],
  ['One ask about a person, costing almost nothing', '✗ ⚠ **neither ask is about a person** — **and there is one available: tell the plater we are getting quotations before he hears it from a competitor**'],
], [3.2, 2.8]));
out.push(p('⚠ **Sample band-4 review:** _"Criterion: one ask about a person. The line I am marking is **_Two quotations from the three platers in Aleppo we have never asked._** What I found: Aleppo plating is a small trade and he will hear about this within a week. One sentence — *and I will telephone him first* — costs nothing and is the difference between asking the market and going behind a man you have used for eleven years."_ ⚠ **That review finds the unit\'s third ask in a paper that had two.** **It is the model for what the *ask about a person* criterion is for.**'));
out.push(stage('6R', 'Share'));
out.push(p('Two or three read only their promise not to come back, **or their declared second step.** ⚠ **The class says whether they believe it.** ⚠ **The believable ones are tied to a number** — *thirty-five is below forty* — **or state the next step plainly.** **A promise with neither is read as a tactic, correctly.**'));
out.push(stage('7', 'Write freely – sample (230 words)'));
out.push(sample(null, [
  'I asked for a second telephone line in 2014 and was refused four times, and the thing I should have asked for cost about nothing.',
  'What I wanted was a second line into the office, because one line meant that every time a customer rang to chase an order, the line was engaged for the supplier who was ringing about the same order. I made the case four times in eighteen months with the number of missed calls on it.',
  'Agreeing would have cost the owner about ninety a month and, much more than that, it would have meant accepting that an arrangement he had set up himself when there were three of us was no longer adequate for eleven. He had said more than once that we managed perfectly well. Each refusal made the fifth request harder.',
  'What I should have asked for was an answering machine, which cost forty once and nothing afterwards, and which would have told me how many calls we were actually missing. It conceded his whole point — that one line was enough — and it would have produced the figure that settled it inside a month.',
  'Nobody ever offered it, including me, because I had spent eighteen months asking for the line and the answering machine felt like losing.',
  'We got a second line in 2016, after a customer complained to him directly. The figure that persuaded him was one complaint, and I had four hundred missed calls.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **Sample:** _"Criterion: was the hidden cost about the argument or about the person? The line I copied is **_it would have meant accepting that an arrangement he had set up himself when there were three of us was no longer adequate for eleven._** What I found: about the person, entirely — and your last line proves it, because one complaint from outside cost him nothing to accept and four hundred missed calls from inside cost him the arrangement."_'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect all three hidden costs to be about the person rather than the argument, and expect two of three cases in which no smaller version was ever offered by anybody.** ⚠ **Name the reason the sample gives, because learners recognise it: by the time you have asked four times, the small version feels like losing** — **and so the one ask that would have been granted is the one nobody makes.**'));
out.push(box('Homework – marking note', [
  'The final text is marked for the content.',
  '⚠ **The second part asks them to question twice whether the smaller ask would satisfy them.** ⚠ **Accept *no* as an answer and teach the sample\'s remedy**: **declare the second step in the same paper.** **A declared sequence is honest and grantable; an undeclared one is the tactic the cycle warns against.**',
], C.lblue, C.navy));

// ===================== 3.6 =====================
out.push(pb());
out.push(h2('3.6  The paragraph you show them first'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Expect almost nobody to have done it.** **Where somebody has, give the whole of this stage to them** — **the class will believe a colleague before it believes the book.**'));
out.push(p('**b**  The **second** is the harder offer. ⚠ **It says what the paragraph is about, it offers a reading rather than a mention, and it promises a change if it is unfair** — **three commitments against *I hope that is all right*, which makes none.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **_Approved._** **He did not approve them, he set them** — *approved* **means somebody brought him a figure and he agreed, and nobody brought him anything.**  2 ⚠ **That the sheet with no line for walk-in trade is also his: he drew it up in 1998 and nobody has changed it since.**'));
out.push(p('⚠ **Two things in this track are the cycle.** **First, the correction makes the sentence *harder* on him and he insists on it**, because ⚠ *approved* **would send Mr Attar looking for a proposal that nobody made** — **a vaguer and larger charge that would attach to him anyway.** ⚠ **Second, the closing line, which is the reason the move works at all: _a man who hears a hard paragraph read to his face argues with the paragraph; a man who finds it in a file argues with the person._**'));
out.push(p('**Language box – Practise (sample):**  _"There is a paragraph in this about the way the inspection list was drawn up. I want to read it to you before it goes, and if it is unfair I will change it. — *The roof above the north corner of the fourth store has not been inspected since 2019. It is not on the inspection list, and the list was drawn up in this office.* — Say *drawn up* again. — It was not drawn up. It was copied from the old gate book in 2019 when the stores were renumbered, and three of the entries are stores we no longer use. ⚠ **Then the list is not a list, it is a copy of a list of a building that has changed** — **and that is a better sentence and I would not have had it.**"_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', '_(softening)_ There is, um, a paragraph here which, to some extent, touches on the allocations. The 2019 and 2021 figures… didn\'t, perhaps, fully account for walk-in trade, which is, of course, quite a significant proportion.'],
  ['B', 'So what you have written is that I have been getting the Homs allocation wrong for four years and nobody has told me.'],
  ['A', 'That is not what it says.'],
  ['B', 'It is what I heard.'],
  ['A', '_(reads again, one speed)_ The 2019 and 2021 Homs allocations were set on the standard seasonal figure and did not count walk-in trade, which is about half of what that shop sells in a season.'],
  ['B', 'That is two years and one sheet. The first version was four years and me.'],
  ['A', 'I added all of that with my voice.'],
  ['B', 'You added it with the pauses. Read it the way it is written and I will argue with the writing.'],
]));
out.push(p('⚠ **Role card 2 is the strongest demonstration in Unit 3 and takes four minutes.** ⚠ **The listener will reliably hear something worse than was written**, because a hesitation is filled by the person listening, and what they have available to fill it with is their own worst case. **Run it, then have A read the paragraph flat, and have B say what changed.**'));
out.push(stage('3R', 'Perform'));
out.push(p('Listeners write the challenged word and what it implied, and the fact the subject gave. **Typical errors:** an offer that does not say what the paragraph is about · a reading that softens as it goes · ⚠ **and the content fault, which is a writer who defends the paragraph instead of taking the correction.** **The subject is the only person in the building who knows which verb is true.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['Who it is about', 'What I will say before reading', 'The word I expect to be challenged', 'What they might give me'], [
  ['Mr Ayoub', '⚠ **that there is a paragraph about a decision of his, and I will change it if it is unfair**', '⚠ **_approved_**', '⚠ **that he set the figures himself, and that the sheet is his from 1998**'],
  ['Mr Attar', 'that it is about the release form and not about his department', '*failed to record*', 'that he asked for the line in 2019 and was refused'],
  ['Lina', 'that it is about the price list and that she is not at fault in it', '⚠ **_quoted incorrectly_**', '**that the list on the wall is the only one she has ever been shown**'],
], [1.2, 1.9, 1.7, 1.6]));
out.push(stage('4R', 'Report – sample'));
out.push(sample(null, ['"The paragraph is about Mr Ayoub. I will say that it concerns a decision of his and that I will change it if it is unfair. The word I expect to be challenged is *approved*. And what he might give me is how the figure was actually arrived at."', '⚠ **Count how many expect to be given a fact: it should be most of the room by this point in the unit.** ⚠ **Then ask how many have ever pre-read a paragraph, and expect almost none** — **and let the gap between the two numbers sit there without comment.**']));
out.push(stage('5', 'Read'));
out.push(p('**1** ⚠ **The *after* version is harder on him, and he dictated the difference.** *You set both figures yourself, in both years, in about four minutes* **is a worse sentence about a man than** *they were approved by you*, **and it is the true one, and he preferred it.**  **2** ⚠ **Because a reader who sees *approved* goes looking for the proposal and finds that nobody made one** — **and then the story is not that he set a figure quickly but that something was approved in the company with no proposal behind it**, ⚠ **which is a larger charge and a vaguer one, and would have attached itself to him anyway.**  **3** ⚠ **It turns the Homs seasons from two mistakes by a man into one missing line on a form that has outlived everybody\'s memory of it** — **and that is the version that can go in front of Mr Attar without anybody having to be at fault.**'));
out.push(stage('6', 'Write with help – sample (149 words)'));
